import React, { useState } from "react";
import "./Form.css";

function Form() {
  const [skills, setSkills] = useState([""]);
  const [projects, setProjects] = useState([
    { name: "", description: "", technology: "" },
  ]);

  // Add skill
  const handleAddSkill = () => {
    setSkills([...skills, ""]);
  };

  // Update the value of a specific skill
  const handleSkillChange = (index, value) => {
    const updatedSkills = [...skills];
    updatedSkills[index] = value;
    setSkills(updatedSkills);
  };

  // Remove a specific skill input
  const handleRemoveSkill = (index) => {
    const updatedSkills = skills.filter((_, i) => i !== index);
    setSkills(updatedSkills);
  };

   // Add a new project
   const handleAddProject = () => {
    setProjects([...projects, { name: "", description: "", technology: "" }]);
  };

  // Update a specific project field
  const handleProjectChange = (index, field, value) => {
    const updatedProjects = [...projects];
    updatedProjects[index][field] = value;
    setProjects(updatedProjects);
  };

  // Remove a specific project
  const handleRemoveProject = (index) => {
    const updatedProjects = projects.filter((_, i) => i !== index);
    setProjects(updatedProjects);
  };


  // Handle form submission
  const handleSubmit = (event) => {
    event.preventDefault();
    console.log("Submitted Skills:", skills);
  };

  return (
    <div className="form-container">
      <form onSubmit={handleSubmit} className="form">
      <h2>PROFILE</h2>
      <input type="text" placeholder="Name" required />
      <input type="file" />
      <input type="text" placeholder="Role" required />
      <input type="date" required />

      <h2>ABOUT SECTION</h2>
      <textarea placeholder="Professional Summary"  />

      {/* Skills Section */}
    
        <h2>Add Your Skills</h2>
        {skills.map((skill, index) => (
          <div key={index} className="input-group">
            <input
              type="text"
              value={skill}
              onChange={(e) => handleSkillChange(index, e.target.value)}
              placeholder={`Skill ${index + 1}`}
              className="input"
            />
            <button
              type="button"
              onClick={() => handleRemoveSkill(index)}
              className="remove"
            >
              Remove
            </button>
          </div>
        ))}
        <div className="button-group">
          <button type="button" onClick={handleAddSkill}>
            Add Skill
          </button>
        </div>
          {/* Projects Section */}
        <h2>Add Your Projects</h2>
        {projects.map((project, index) => (
          <div key={index} className="project-group">
            <input
              type="text"
              value={project.name}
              onChange={(e) =>
                handleProjectChange(index, "name", e.target.value)
              }
              placeholder={`Project Name ${index + 1}`}
              className="input"
            />
            <textarea
              value={project.description}
              onChange={(e) =>
                handleProjectChange(index, "description", e.target.value)
              }
              placeholder="Project Description"
              rows="3"
              className="textarea"
            ></textarea>
            <input
              type="text"
              value={project.technology}
              onChange={(e) =>
                handleProjectChange(index, "technology", e.target.value)
              }
              placeholder="Technology Used"
              className="input"
            />
            <button
              type="button"
              onClick={() => handleRemoveProject(index)}
              className="remove"
            >
              Remove Project
            </button>
          </div>
        ))}
        <div className="button-group">
          <button type="button" onClick={handleAddProject}>
            Add Project
          </button>
        </div>

        {/* Contact Section */}
        <h2>Contact Section</h2>
        <input 
            type="email" 
            placeholder="Email" 
            required />
        <input 
            type="number" 
            placeholder="Phone Number" 
            required />
        <input type="url" name="linkedIn"  
            placeholder="LinkedIn Link" pattern="https://.*" 
            size="30" required />
        <input type="url" name="github"  
            placeholder="GitHub Link" pattern="https://.*" 
            size="30" required /> 
        <button type="submit">Submit</button>
      </form>
    </div>
  );
}

export default Form;
